    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const r1i = issueInvoice(r1.value, []);
  const totals = invoiceTotals(r1i.value);
  const payment = 5000;
  const r1p = recordPayment(r1i.value, { amount: payment, date: '2026-10-08' });

  const d = dashboard([r1p.value], '2026-10-15');

  assert.equal(d.outstanding, totals.total - payment);
});

